"""GRPO shape: cr_compositor_only — long-story variant (30 samples).

Companion to shape_cr_compositor_only.py. Each user_goal starts with
"Here's my story I want to process: " followed by an original ~200-word
story. Same chain as the short-brief file: Story → Screenplay → KeyFrame
→ Video → Compositor (no audio overlay).
"""
from __future__ import annotations


_REJECT = (
    "Reject MusicAgent / AmbienceAgent / AudioMixAgent (no audio overlay requested), "
    "TranscriptionAgent / TranslationAgent (no subtitles), VideoAnalysisAgent / "
    "IntakeVideoAgent / StyleTransferAgent / VideoExtendAgent / HighlightAgent (no "
    "video uploaded), NarrationAgent / IllustrationAgent / NarratorAgent (not a "
    "slideshow / illustrated-storytelling format)."
)


def _make(theme, blueprint_arc, scene_break, keyframe_settings, render_aesthetic, composite_descriptor):
    """Same shape as short-brief helper; slightly different rationale framing."""
    return {
        "rationale": (
            f"{theme} mini-drama from a user-provided novella, no audio overlay. "
            f"StoryAgent drafts the {blueprint_arc} blueprint from the supplied story. "
            f"ScreenplayAgent breaks it into {scene_break} scenes. KeyFrameAgent plans "
            f"keyframes for the {keyframe_settings} settings from text alone. VideoAgent "
            "assembles the multi-shot film. CompositorAgent muxes the final mp4 with "
            "inter-shot transitions. " + _REJECT
        ),
        "intents": [
            f"Draft the {theme} story blueprint — {blueprint_arc} arc — from the user's supplied novella.",
            f"Decompose the {blueprint_arc} arc into {scene_break} scenes.",
            f"Plan keyframes for the {keyframe_settings} settings; text-only generation, no reference images supplied.",
            f"Render per-shot clips preserving {render_aesthetic} visual continuity.",
            f"Composite the final {composite_descriptor} mp4 with inter-shot transitions.",
        ],
    }


